base<-"analysis/comp_assessments";db<-file.path(base,"database");cache<-file.path(base,"source_cache/nefsc_american_plaice_5yz/2026")
id<-"nefsc_american_plaice_5yz_2026_mt_provisional"; earlier<-"nefsc_american_plaice_5yz_2022_run29f4"
report_url<-"https://apps-nefsc.fisheries.noaa.gov/saw/sasi_files.php?year=2026&species_id=2&stock_id=4&review_type_id=6&filename=2026_PLA_GMGB.zip"
peer_url<-"https://www.fisheries.noaa.gov/s3/fileserve?filepath=2026-10/september-2026-management-track-peer-review-panel-report_20261007.pdf"
verify<-function(f,h){p<-file.path(cache,f);stopifnot(digest::digest(readBin(p,"raw",n=file.info(p)$size),algo="sha256",serialize=FALSE)==h);p}
report<-pdftools::pdf_text(verify("American_plaice_SAR_9_4_2026.pdf","ca8635e2b1e2c2f23108707d71f894e3c4f81e308d2ee70eb81ab9e0ef8b9962"))
peer<-pdftools::pdf_text(verify("September_2026_MT_Peer_Review_Panel_Report.pdf","6a9713341e1d98ddbad21d1d7eb8bd898adc7964d4f06f5b6d21821a067782a0"))
p<-gsub("[[:space:]]+"," ",paste(peer,collapse=" "));stopifnot(grepl("2026 Management Track Assessment for American plaice is technically sufficient",p,fixed=TRUE),grepl("candidate model used for the assessment reviewed, MT3",p,fixed=TRUE),grepl("12,711 mt",p,fixed=TRUE),grepl("4,700 mt",p,fixed=TRUE),grepl("1,564 mt in 2025",p,fixed=TRUE))
lines<-trimws(strsplit(report[10],"\n")[[1]]); commercial<-lines[startsWith(lines,"Commercial ")];total<-lines[startsWith(lines,"Total Catch")];stopifnot(length(commercial)==2,length(total)==1)
nums<-function(l,label){v<-as.numeric(strsplit(trimws(gsub(",","",substring(l,nchar(label)+1),fixed=TRUE)),"[[:space:]]+")[[1]]);stopifnot(length(v)==11,all(is.finite(v)));v}
land<-nums(commercial[1],"Commercial");discard<-nums(commercial[2],"Commercial");total<-nums(total,"Total Catch");stopifnot(tail(total,1)==1564,all(abs(land+discard-total)<=1))
blank<-function(f,n=1L){cols<-names(read.csv(file.path(db,f),nrows=0));z<-as.data.frame(matrix("",n,length(cols)),stringsAsFactors=FALSE);names(z)<-cols;if("assessment_id"%in%cols)z$assessment_id<-id;z}
input<-function(v,measure,fleet,note){z<-blank("inputs.csv",11);z$type<-"catch";z$measure<-measure;z$basis<-"biomass";z$fleet<-fleet;z$year<-2015:2025;z$year_basis<-"calendar_year";z$value<-v;z$unit<-"metric tonnes";z$source_type<-"official_table";z$source_reference<-paste(report_url,"Table 1");z$notes<-note;z}
inputs<-rbind(input(total,"total_biomass","Total catch","Pre-review report Table 1 total catch; components overlap this total and are not independent observations. September peer review confirms 2025 total 1564 t."),input(land,"landings_biomass","Commercial landings","Pre-review report Table 1 component of total catch; not a separate additional observation."),input(discard,"discard_biomass","Commercial discards","Pre-review report Table 1 component of total catch; not a separate additional observation."))
outputs<-blank("outputs.csv",3);outputs$type<-c("mortality","biomass","catch");outputs$measure<-c("Fmsy","Bmsy","msy");outputs$value<-c(.43,12711,4700);outputs$lwr<-c(.37,10267,3792);outputs$upr<-c(.49,15737,5826);outputs$unit<-c("per year","metric tonnes","metric tonnes");outputs$source_type<-"official_document";outputs$source_reference<-peer_url;outputs$notes<-c("F40% SPR proxy; 90% interval from pre-review report Table 3.", "Spawning-stock biomass proxy SSBMSY; 90% interval from pre-review report Table 3.", "MSY proxy; 90% interval from pre-review report Table 3.")
a<-blank("assumptions.csv",2);a$component<-"assessment";a$setting<-c("peer_review_outcome","model_update");a$value<-c("2026 MT3 technically sufficient for status and scientific catch advice; all TORs met","2026 model includes corrected 2018-2023 catch age composition and weights, revised survey selectivity, and no lognormal adjustment");a$source_reference<-peer_url;a$notes<-c("Peer review acceptance is verified; management adoption for advice has not yet been established.","Peer-reviewed MT3 follows 2024 WHAM. The retained report itself is marked pre-decisional.")
as<-read.csv(file.path(db,"assessments.csv"),colClasses="character",na.strings="",check.names=FALSE)
new<-as[as$assessment_id==id,,drop=FALSE];old<-as[as$assessment_id==earlier,,drop=FALSE];stopifnot(nrow(new)==1,nrow(old)==1);old$is_current<-"FALSE";new$is_current<-"TRUE";new$is_applied<-"FALSE";new$model_version<-"2026 Management Track MT3; peer reviewed, report pre-decisional";new$assessment_type<-"management_track_update";new$notes<-"The 2026 MT3 assessment passed September 2026 peer review. Available report remains pre-decisional and no native inputs or age surfaces were found. Advice adoption has not been verified; is_applied remains FALSE."
write_rows<-function(f,z,key){path<-file.path(db,f);raw<-rawToChar(readBin(path,"raw",n=file.info(path)$size));l<-strsplit(raw,"\n",fixed=TRUE)[[1]];sel<-which(startsWith(l,paste0('"',key,'",')));stopifnot(length(sel)==1,identical(names(z),names(read.csv(path,nrows=0))));tmp<-tempfile(tmpdir=db);on.exit(unlink(tmp),add=TRUE);write.table(z,tmp,sep=",",quote=TRUE,row.names=FALSE,col.names=FALSE,na="",fileEncoding="UTF-8");r<-readLines(tmp,encoding="UTF-8",warn=FALSE);l[sel]<-paste0(r,if(endsWith(l[sel],"\r"))"\r" else "");writeBin(charToRaw(paste0(paste(l,collapse="\n"),if(endsWith(raw,"\n"))"\n" else "")),tmp);if(!file.copy(tmp,path,overwrite=TRUE))stop("write failed")}
append_selected<-function(f,z,marker){path<-file.path(db,f);raw<-rawToChar(readBin(path,"raw",n=file.info(path)$size));l<-strsplit(raw,"\n",fixed=TRUE)[[1]];l<-l[!(startsWith(l,paste0('"',id,'",'))&grepl(marker,l,fixed=TRUE))];tmp<-tempfile(tmpdir=db);on.exit(unlink(tmp),add=TRUE);write.table(z,tmp,sep=",",quote=TRUE,row.names=FALSE,col.names=FALSE,na="",fileEncoding="UTF-8");r<-readLines(tmp,encoding="UTF-8",warn=FALSE);writeBin(charToRaw(paste0(paste(c(l,r),collapse="\n"),if(endsWith(raw,"\n"))"\n" else "")),tmp);if(!file.copy(tmp,path,overwrite=TRUE))stop("write failed")}
if(identical(Sys.getenv("TAM_SOURCE_DRY_RUN"),"1"))cat("Plaice 2026 peer review and source tables verified.\n") else {write_rows("assessments.csv",old,earlier);write_rows("assessments.csv",new,id);append_selected("inputs.csv",inputs,"2026_PLA_GMGB.zip");append_selected("outputs.csv",outputs,peer_url);append_selected("assumptions.csv",a,peer_url);cat("Updated plaice 2026 peer review, catches and reference points.\n")}
